function authMiddleware(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: 'No token provided' });
    }
    const token = authHeader.split(' ')[1];
    try {
        const decoded = jwt.verify(token, JWT_SECRET, { issuer: 'app' });
        req.user = decoded;
        next();
    } catch (err) {
        if (err.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'Token expired' });
        }
        return res.status(401).json({ error: 'Invalid token' });
    }
}

function rateLimitMiddleware(req, res, next) {
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();
    const windowMs = 15 * 60 * 1000;
    const maxRequests = 100;
    if (!requestCounts.has(ip)) requestCounts.set(ip, []);
    const timestamps = requestCounts.get(ip).filter(t => now - t < windowMs);
    if (timestamps.length >= maxRequests) {
        const retryAfter = Math.ceil((timestamps[0] + windowMs - now) / 1000);
        res.set('Retry-After', retryAfter);
        res.set('X-RateLimit-Remaining', '0');
        return res.status(429).json({ error: 'Too many requests' });
    }
    timestamps.push(now);
    requestCounts.set(ip, timestamps);
    res.set('X-RateLimit-Remaining', String(maxRequests - timestamps.length));
    next();
}

function sanitize(value) {
    if (typeof value === 'string') {
        let clean = value.replace(/<[^>]*>/g, '');
        const sqlPatterns = /('|--|;|DROP|DELETE|INSERT|UPDATE|ALTER|EXEC)/gi;
        if (sqlPatterns.test(clean)) clean = clean.replace(sqlPatterns, '');
        return clean;
    }
    if (Array.isArray(value)) return value.map(sanitize);
    if (value && typeof value === 'object') {
        const result = {};
        for (const [k, v] of Object.entries(value)) {
            if (!k.startsWith('$')) result[k] = sanitize(v);
        }
        return result;
    }
    return value;
}

function sanitizeMiddleware(req, res, next) {
    if (req.body) req.body = sanitize(req.body);
    if (req.query) req.query = sanitize(req.query);
    if (req.params) req.params = sanitize(req.params);
    next();
}

