import jwt
import time
import re
import html
from functools import wraps
from collections import defaultdict

JWT_SECRET = 'super-secret-key'
request_counts = defaultdict(list)

def auth_middleware(f):
    @wraps(f)
    def decorated(request, *args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return {'error': 'No token provided'}, 401
        token = auth_header.split(' ')[1]
        try:
            decoded = jwt.decode(token, JWT_SECRET, algorithms=['HS256'], issuer='app')
            request.user = decoded
        except jwt.ExpiredSignatureError:
            return {'error': 'Token expired'}, 401
        except jwt.InvalidTokenError:
            return {'error': 'Invalid token'}, 401
        return f(request, *args, **kwargs)
    return decorated

def rate_limit_middleware(max_requests=100, window_seconds=900):
    def decorator(f):
        @wraps(f)
        def decorated(request, *args, **kwargs):
            ip = request.remote_addr
            now = time.time()
            request_counts[ip] = [t for t in request_counts[ip] if now - t < window_seconds]
            if len(request_counts[ip]) >= max_requests:
                retry_after = int(request_counts[ip][0] + window_seconds - now)
                return {'error': 'Too many requests', 'retry_after': retry_after}, 429
            request_counts[ip].append(now)
            return f(request, *args, **kwargs)
        return decorated
    return decorator

def sanitize_input(data):
    if isinstance(data, str):
        clean = re.sub(r'<[^>]*>', '', data)
        clean = re.sub(r"('|--|;|DROP|DELETE|INSERT|UPDATE|ALTER|EXEC)", '', clean, flags=re.I)
        return clean
    if isinstance(data, list):
        return [sanitize_input(item) for item in data]
    if isinstance(data, dict):
        return {k: sanitize_input(v) for k, v in data.items() if not k.startswith('$')}
    return data
